                        if n / area >= 0.80:
                            candidates.append((area, n, r0, r1, c0, c1, color))

    # Keep the largest dense rectangles first. All other colors/noise are
    # erased; every cell in a detected rectangle is restored to its fill color.
    candidates.sort(reverse=True)
